import mido, math, statistics
from collections import Counter, defaultdict, deque

GM = ('Acoustic Grand Piano,Bright Acoustic Piano,Electric Grand Piano,Honky-tonk Piano,Electric Piano 1,Electric Piano 2,Harpsichord,Clavinet,Celesta,Glockenspiel,Music Box,Vibraphone,Marimba,Xylophone,Tubular Bells,Dulcimer,Drawbar Organ,Percussive Organ,Rock Organ,Church Organ,Reed Organ,Accordion,Harmonica,Tango Accordion,Acoustic Guitar nylon,Acoustic Guitar steel,Electric Guitar jazz,Electric Guitar clean,Electric Guitar muted,Overdriven Guitar,Distortion Guitar,Guitar harmonics,Acoustic Bass,Electric Bass finger,Electric Bass pick,Fretless Bass,Slap Bass 1,Slap Bass 2,Synth Bass 1,Synth Bass 2,Violin,Viola,Cello,Contrabass,Tremolo Strings,Pizzicato Strings,Orchestral Harp,Timpani,String Ensemble 1,String Ensemble 2,Synth Strings 1,Synth Strings 2,Choir Aahs,Voice Oohs,Synth Voice,Orchestra Hit,Trumpet,Trombone,Tuba,Muted Trumpet,French Horn,Brass Section,Synth Brass 1,Synth Brass 2,Soprano Sax,Alto Sax,Tenor Sax,Baritone Sax,Oboe,English Horn,Bassoon,Clarinet,Piccolo,Flute,Recorder,Pan Flute,Blown Bottle,Shakuhachi,Whistle,Ocarina,Lead square,Lead sawtooth,Lead calliope,Lead chiff,Lead charang,Lead voice,Lead fifths,Lead bass and lead,Pad new age,Pad warm,Pad polysynth,Pad choir,Pad bowed,Pad metallic,Pad halo,Pad sweep,FX rain,FX soundtrack,FX crystal,FX atmosphere,FX brightness,FX goblins,FX echoes,FX sci-fi,Sitar,Banjo,Shamisen,Koto,Kalimba,Bag pipe,Fiddle,Shanai,Tinkle Bell,Agogo,Steel Drums,Woodblock,Taiko Drum,Melodic Tom,Synth Drum,Reverse Cymbal,Guitar Fret Noise,Breath Noise,Seashore,Bird Tweet,Telephone Ring,Helicopter,Applause,Gunshot').split(',')
PC = ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B']
DR = {35:'bass drum 2',36:'bass drum',37:'side stick',38:'snare',39:'hand clap',40:'electric snare',41:'low floor tom',42:'closed hi-hat',43:'high floor tom',44:'pedal hi-hat',45:'low tom',46:'open hi-hat',47:'low-mid tom',48:'high-mid tom',49:'crash cymbal',50:'high tom',51:'ride cymbal',52:'Chinese cymbal',53:'ride bell',54:'tambourine',55:'splash cymbal',56:'cowbell',57:'crash cymbal 2',59:'ride cymbal 2'}
def note(n): return PC[n%12]+str(n//12-1)
def top(c, n=6): return ', '.join(str(k)+':'+str(v) for k,v in c.most_common(n))
def adapt(path):
    try:
        mid=mido.MidiFile(path, clip=True)
    except Exception as e:
        return {'text':'Could not parse MIDI file: '+str(e)[:200]}
    ppq=mid.ticks_per_beat
    lines=['MIDI format %s, %d tracks, %s ticks per quarter note.'%(mid.type,len(mid.tracks),ppq)]
    events=[]; meta=[]; tempos=[]; meters=[]; keys=[]; end=0; truncated=False
    for ti,tr in enumerate(mid.tracks):
        t=0
        for msg in tr:
            t+=msg.time; end=max(end,t)
            if len(events)>=300000:
                truncated=True; break
            events.append((t,ti,len(events),msg))
            if msg.is_meta:
                if msg.type=='set_tempo': tempos.append((t,msg.tempo))
                elif msg.type=='time_signature': meters.append((t,msg.numerator,msg.denominator))
                elif msg.type=='key_signature': keys.append((t,msg.key))
                elif msg.type in ('track_name','instrument_name','text','lyrics','marker','copyright','cue_marker'):
                    s=str(getattr(msg,'text',getattr(msg,'name',''))).replace('\n',' ').strip()
                    if s: meta.append((msg.type,s[:160]))
        if truncated: break
    if truncated: lines.append('Analysis limited to first 300000 events; duration and counts may be incomplete.')
    if ppq<=0:
        lines.append('SMPTE timing; beat-based measurements unavailable.')
        ppq=480
    events.sort(key=lambda x:(x[0],x[1],x[2]))
    tempos.sort(); meters.sort(); keys.sort()
    if tempos:
        lines.append('Tempo events: '+', '.join('beat %.1f: %.1f BPM'%(t/ppq,60000000/v) for t,v in tempos[:8]))
    else: lines.append('No tempo metadata; MIDI default is 120 BPM.')
    if meters: lines.append('Meter events: '+', '.join('beat %.1f: %d/%d'%(t/ppq,a,b) for t,a,b in meters[:8]))
    else: lines.append('No time signature metadata; MIDI default is 4/4.')
    if keys: lines.append('Key signature metadata: '+', '.join('beat %.1f: %s'%(t/ppq,k) for t,k in keys[:8]))
    if meta:
        seen=[]
        for typ,s in meta:
            item=typ+': '+s
            if item not in seen: seen.append(item)
        lines.append('Embedded text metadata (not necessarily genre): '+'; '.join(seen[:12]))
    else: lines.append('No descriptive text or genre metadata found.')
    tempo=500000; last=0; seconds=0
    for t,v in tempos:
        if t>end: break
        seconds+=(t-last)*tempo/(ppq*1000000); last=t; tempo=v
    seconds+=(end-last)*tempo/(ppq*1000000)
    lines.append('Length: %.1f quarter-note beats, approximately %.1f seconds.'%(end/ppq,seconds))
    programs=[0]*16; banks=[0]*16; active=defaultdict(deque); notes=[]; counts=Counter(); progcounts=defaultdict(Counter); velocities=defaultdict(list); starts=defaultdict(list); pitches=defaultdict(list); drums=Counter(); controls=Counter()
    for t,ti,idx,msg in events:
        typ=msg.type
        if typ=='program_change': programs[msg.channel]=msg.program
        elif typ=='control_change':
            controls[(msg.channel,msg.control)]+=1
            if msg.control==0: banks[msg.channel]=msg.value
        elif typ=='note_on' and msg.velocity>0:
            ch=msg.channel; counts[ch]+=1; progcounts[ch][(programs[ch],banks[ch])]+=1
            velocities[ch].append(msg.velocity); starts[ch].append(t); pitches[ch].append(msg.note)
            if ch==9: drums[msg.note]+=1
            active[(ch,msg.note)].append((t,msg.velocity,ti))
        elif typ=='note_off' or (typ=='note_on' and msg.velocity==0):
            ch=msg.channel; q=active[(ch,msg.note)]
            if q:
                st,vel,track=q.popleft(); notes.append((st,t,ch,msg.note,vel,track))
    total=sum(counts.values()); lines.append('Note attacks: %d; active MIDI channels: %d.'%(total,len(counts)))
    if drums: lines.append('Channel 10 percussion hits: '+', '.join('%s (%d): %d'%(DR.get(k,'drum'),k,v) for k,v in drums.most_common(10)))
    for ch,n in counts.most_common(10):
        ps=pitches[ch]; vs=velocities[ch]; ts=starts[ch]; ds=[(b-a)/ppq for a,b,c,p,v,tr in notes if c==ch and b>=a]
        inst=[]
        for (p,b),cnt in progcounts[ch].most_common(3):
            inst.append(('percussion kit' if ch==9 else GM[p])+' (%d notes%s)'%(cnt,', bank '+str(b) if b else ''))
        unique=sorted(set(ts)); gaps=[(b-a)/ppq for a,b in zip(unique,unique[1:]) if b>a]
        simultaneous=n-len(unique)
        desc='Channel %d: %s; %d attacks, range %s-%s, velocity median %d (range %d-%d)'%(ch+1,', '.join(inst),n,note(min(ps)),note(max(ps)),statistics.median(vs),min(vs),max(vs))
        if ds: desc+=', median note length %.2f beats'%statistics.median(ds)
        if gaps: desc+=', median onset spacing %.2f beats'%statistics.median(gaps)
        desc+=', %d simultaneous extra attacks.'%simultaneous
        lines.append(desc)
        if ch!=9:
            lines.append('  Frequent pitches: '+top(Counter(note(p) for p in ps),6)+'.')
            seq=sorted([(t,p) for t,p in zip(ts,ps)])[:24]
            if seq: lines.append('  Opening attacks (beat:pitch): '+', '.join('%.2f:%s'%(t/ppq,note(p)) for t,p in seq)+'.')
    melodic=[x for x in notes if x[2]!=9]
    if melodic:
        pc=Counter(PC[p%12] for a,b,c,p,v,tr in melodic)
        lines.append('Pitch-class attack counts: '+top(pc,12)+'.')
        groups=defaultdict(set)
        for a,b,c,p,v,tr in melodic: groups[a].add(p%12)
        chords=Counter()
        for s in groups.values():
            if len(s)>=3:
                for root in sorted(s):
                    for intervals,name in [({0,4,7},'major'),({0,3,7},'minor'),({0,3,6},'diminished')]:
                        if {(root+i)%12 for i in intervals}.issubset(s): chords[PC[root]+' '+name]+=1
        if chords: lines.append('Simultaneous note-on triad subsets (not a full harmonic analysis): '+top(chords,8)+'.')
        # Beat-position distribution reveals regularity and offbeat emphasis.
        phases=Counter(round((a%ppq)/ppq*4)/4 for a,b,c,p,v,tr in melodic)
        lines.append('Melodic attack positions within quarter-note beat (fraction:count): '+top(phases,6)+'.')
    if controls:
        sustain=sum(v for (ch,cc),v in controls.items() if cc==64)
        if sustain: lines.append('Sustain pedal controller events: %d.'%sustain)
    lines.append('MIDI specifies note events and instrument programs, not actual rendered timbre; genre can be ambiguous from MIDI alone.')
    return {'text':'\n'.join(lines)[:4000]}
